insert into public.training_sources(source_key,authority,title,source_type,canonical_url,publication_date,checked_on,license_kind,reuse_policy,normative_status,topics,notes,metadata)
values ('gu-dm2-2021-antincendio','Ministero dell''Interno - Gazzetta Ufficiale','D.M. 2 settembre 2021 - Gestione della sicurezza antincendio nei luoghi di lavoro','normative_source','https://www.gazzettaufficiale.it/eli/id/2021/10/04/21A05748/SG',date '2021-09-02',date '2026-10-16','public_official','reference_and_original_rewrite','vigente',array['antincendio','addetti antincendio','formazione','aggiornamento','livello 1','livello 2','livello 3','GSA'],'Fonte normativa primaria per programmi, durate, aggiornamento e gestione della sicurezza antincendio.',jsonb_build_object('gu','Serie Generale n.237 del 04-10-2021','article_ref','D.Lgs. 81/2008 art. 46'))
on conflict (source_key) do update set authority=excluded.authority,title=excluded.title,source_type=excluded.source_type,canonical_url=excluded.canonical_url,publication_date=excluded.publication_date,checked_on=excluded.checked_on,reuse_policy=excluded.reuse_policy,normative_status=excluded.normative_status,topics=excluded.topics,notes=excluded.notes,metadata=excluded.metadata,updated_at=now();
update public.training_sources set checked_on=date '2026-10-16',updated_at=now() where source_key in ('vvf-materiali-antincendio','normattiva-dlgs81-vigente');
update public.training_blueprints set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('legal_reviewed_on','2026-10-16','regulatory_basis','D.Lgs. 81/2008 art. 46 + D.M. 2 settembre 2021 Allegato III','content_ready',true,'renewal_interval_months',60,'level_1',jsonb_build_object('total_minutes',240,'theory_minutes',120,'practice_minutes',120),'level_2',jsonb_build_object('total_minutes',480,'theory_minutes',300,'practice_minutes',180),'level_3',jsonb_build_object('total_minutes',960,'theory_minutes',720,'practice_minutes',240),'practical_completion_not_digital',true,'classification_rule','Il livello va determinato in base ai criteri del D.M. 2 settembre 2021 e alla valutazione antincendio dell’attività; non inferire il livello dal solo titolo del corso.','publication_policy','draft_review_before_linking'),updated_at=now() where stable_key='fire_initial';
update public.training_blueprints set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('legal_reviewed_on','2026-10-16','regulatory_basis','D.M. 2 settembre 2021 Allegato III','content_ready',true,'renewal_interval_months',60,'level_1',jsonb_build_object('total_minutes',120,'theory_minutes',0,'practice_minutes',120),'level_2',jsonb_build_object('total_minutes',300,'theory_minutes',120,'practice_minutes',180),'level_3',jsonb_build_object('total_minutes',480,'theory_minutes',300,'practice_minutes',180),'practical_completion_not_digital',true,'publication_policy','draft_review_before_linking'),updated_at=now() where stable_key='fire_update';
update public.training_blueprint_sections set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('legal_reviewed_on','2026-10-16','dm2_2021_practical_gate',practical,'completed_digitally',case when practical then false else null end),updated_at=now() where blueprint_key in ('fire_initial','fire_update');
update public.training_blueprint_course_types set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('content_ready',true,'legal_reviewed_on','2026-10-16','didactic_version','fire-authored-v3','practical_gate_required',true,'mapped_course_key',case when blueprint_key='fire_initial' and variant_key='level_1' then 'antincendio_l1' when blueprint_key='fire_initial' and variant_key='level_2' then 'antincendio' when blueprint_key='fire_initial' and variant_key='level_3' then 'antincendio_l3' when blueprint_key='fire_update' and variant_key='level_1' then 'agg_antincendio_l1' when blueprint_key='fire_update' and variant_key='level_2' then 'agg_antincendio_l2' when blueprint_key='fire_update' and variant_key='level_3' then 'agg_antincendio_l3' end),updated_at=now() where blueprint_key in ('fire_initial','fire_update');
update public.training_blueprint_variants set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('content_ready',true,'legal_reviewed_on','2026-10-16','didactic_version','fire-authored-v3','practical_gate_required',true,'mapped_course_key',case when blueprint_key='fire_initial' and variant_key='level_1' then 'antincendio_l1' when blueprint_key='fire_initial' and variant_key='level_2' then 'antincendio' when blueprint_key='fire_initial' and variant_key='level_3' then 'antincendio_l3' when blueprint_key='fire_update' and variant_key='level_1' then 'agg_antincendio_l1' when blueprint_key='fire_update' and variant_key='level_2' then 'agg_antincendio_l2' when blueprint_key='fire_update' and variant_key='level_3' then 'agg_antincendio_l3' end),updated_at=now() where blueprint_key in ('fire_initial','fire_update');
update public.integration_course_catalog set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('content_ready',true,'legal_reviewed_on','2026-10-16','didactic_version','fire-authored-v3','mapped_training_course_key',case external_course_code when 'antincendio_liv1' then 'antincendio_l1' when 'antincendio_liv2' then 'antincendio' when 'antincendio_liv3' then 'antincendio_l3' when 'agg_antincendio_liv1_2h' then 'agg_antincendio_l1' when 'agg_antincendio_liv2_5h' then 'agg_antincendio_l2' when 'agg_antincendio_liv3_8h' then 'agg_antincendio_l3' end),updated_at=now() where source_system='safetymanager' and external_course_code in ('antincendio_liv1','antincendio_liv2','antincendio_liv3','agg_antincendio_liv1_2h','agg_antincendio_liv2_5h','agg_antincendio_liv3_8h');
with target_keys as (select distinct lu.stable_key from public.courses c join public.course_versions cv on cv.course_id=c.id join public.course_modules cm on cm.course_version_id=cv.id join public.course_module_units cmu on cmu.module_id=cm.id join public.learning_unit_versions linked on linked.id=cmu.unit_version_id join public.learning_units lu on lu.id=linked.learning_unit_id where c.stable_key in ('antincendio_l1','antincendio','antincendio_l3','agg_antincendio_l1','agg_antincendio_l2','agg_antincendio_l3') and cv.version_number=(select max(v.version_number) from public.course_versions v where v.course_id=c.id)), target as (select lu.id learning_unit_id,lu.stable_key,lu.title,lu.default_minutes,(select max(v.version_number)+1 from public.learning_unit_versions v where v.learning_unit_id=lu.id) target_version,(select v.content from public.learning_unit_versions v where v.learning_unit_id=lu.id order by v.version_number desc limit 1) old_content,case when lu.stable_key like 'fire:upd:%' then 'update' else 'base' end family,case when lu.stable_key like 'fire:l1:%' or lu.stable_key like 'fire:upd:l1:%' then 1 when lu.stable_key like 'fire:l3:%' or lu.stable_key like 'fire:upd:l3:%' then 3 else 2 end level,lu.stable_key in ('fire:l1:practical','antincendio:pratica-estintori','fire:l3:practical-ext','fire:l3:practical-hose','fire:upd:l1:practice','fire:upd:l2:practice','fire:upd:l3:practice') practical_unit from public.learning_units lu join target_keys tk on tk.stable_key=lu.stable_key), profiled as (select t.*,case when stable_key in ('fire:l1:combustion','antincendio:combustione','fire:l3:combustion') then 'Comprendere combustione, innesco, combustibile, comburente, prodotti dell’incendio e rischi per persone e ambiente per riconoscere precocemente condizioni che possono generare o alimentare un incendio.' when stable_key='antincendio:triangolo' then 'Usare il modello della combustione per comprendere perché le sostanze estinguenti agiscono in modo diverso e perché la scelta del presidio deve essere coerente con materiale coinvolto, ambiente e sicurezza dell’addetto.' when stable_key in ('fire:l1:protection','antincendio:esodo-compartimentazione','fire:l3:passive') then 'Leggere le misure di protezione passiva e l’esodo come sistema: compartimentazione, resistenza e reazione al fuoco, vie di uscita, porte e comportamento degli occupanti devono restare disponibili e coerenti con l’emergenza.' when stable_key in ('antincendio:rivelazione-allarme','fire:l3:detection') then 'Comprendere il ruolo di rivelazione, allarme, controllo di fumo e calore e altri sistemi di sicurezza, distinguendo segnalazione, attivazione, risposta degli addetti e limiti di intervento.' when stable_key in ('antincendio:gsa','fire:l3:gsa') then 'Gestire la sicurezza antincendio in esercizio e in emergenza attraverso controlli, sorveglianza, procedure, informazione, coordinamento e verifica della disponibilità delle misure antincendio.' when stable_key='fire:l3:prevention' then 'Individuare cause e condizioni di incendio nello specifico ambiente di lavoro, controllare sorgenti di innesco, materiali e lavorazioni e collegare prevenzione, manutenzione e comportamento operativo.' when stable_key='fire:l3:control' then 'Conoscere finalità e limiti dei sistemi di controllo dell’incendio e scegliere il presidio solo quando l’intervento iniziale è compatibile con sicurezza personale, caratteristiche del fuoco e via di fuga disponibile.' when stable_key in ('fire:l1:practical','antincendio:pratica-estintori','fire:l3:practical-ext') then 'Esercitare riconoscimento e impiego sicuro dei presidi portatili, controlli preliminari, posizione rispetto a fuoco e via di fuga, distanza efficace e abbandono immediato dell’azione quando l’incendio non è controllabile in sicurezza.' when stable_key='fire:l3:practical-hose' then 'Esercitare uso coordinato di naspi e idranti e gestione di uno scenario integrato, comprendendo alimentazione, stendimento, reazione della linea, comunicazione tra addetti e condizioni che impongono di non procedere.' when stable_key='fire:upd:l1:practice' then 'Rinfrescare esclusivamente in esercitazione le operazioni pratiche essenziali del livello 1: riconoscimento del presidio, controlli, tecnica d’uso, sicurezza, via di fuga e STOP.' when stable_key='fire:upd:l2:theory' then 'Aggiornare incendio, prevenzione, protezione e procedure del livello 2 collegando cambiamenti dell’attività, controlli dei luoghi, allarme, esodo e comportamento dell’addetto.' when stable_key='fire:upd:l2:practice' then 'Rinfrescare in esercitazione l’impiego di estintori, naspi e idranti previsto per il livello 2, con attenzione a preparazione, sicurezza, comunicazione e interruzione dell’azione.' when stable_key='fire:upd:l3:theory1' then 'Riesaminare per il livello 3 combustione, cause, prevenzione, aree a rischio specifico e strategia antincendio, usando scenari complessi e modifiche intervenute nell’attività.' when stable_key='fire:upd:l3:theory2' then 'Riesaminare GSA, controlli, manutenzione, procedure ed emergenza del livello 3, verificando come si coordinano addetti, sistemi di sicurezza e organizzazione.' when stable_key='fire:upd:l3:practice' then 'Rinfrescare praticamente per il livello 3 l’impiego dei presidi e la risposta coordinata a scenario, con debriefing su sicurezza, priorità, comunicazione e condizioni di abbandono.' else 'Collegare rischio incendio, prevenzione, protezione, comportamento dell’addetto e procedure di emergenza in modo operativo e verificabile.' end focus,case when practical_unit then 'Durante un’esercitazione su “'||title||'” cambia una condizione della scena: il corsista deve controllare presidio e via di fuga, dichiarare se procede o si arresta, eseguire la sequenza prevista e motivare la propria decisione nel debriefing.' when family='update' then 'Durante l’aggiornamento sul tema “'||title||'” viene presentato un cambiamento dell’attività o una criticità emersa da controlli/esercitazioni. Individuare cosa deve essere riesaminato e quale comportamento dell’addetto deve cambiare.' else 'In un luogo di lavoro coerente con il livello '||level||' emerge una criticità relativa a “'||title||'”. Identificare pericolo, misura preventiva/protettiva, azione dell’addetto, comunicazione necessaria e condizione che impone di non intervenire direttamente.' end case_text,jsonb_build_array('gu-dm2-2021-antincendio','vvf-materiali-antincendio','normattiva-dlgs81-vigente') source_keys from target t), enriched as (select learning_unit_id,stable_key,target_version,family,level,practical_unit,source_keys,old_content||jsonb_build_object('summary',coalesce(old_content->>'summary','L’addetto antincendio contribuisce alla prevenzione, riconosce l’emergenza, attua le procedure previste e interviene sui presidi solo quando l’azione è compatibile con formazione, scenario e sicurezza personale.'),'detail',coalesce(old_content->>'detail',focus)||' Il materiale deve permettere al corsista di capire cosa osservare, cosa fare, chi avvisare, quando fermarsi e come collegare la propria azione al piano di emergenza e agli altri soggetti.','focus',focus,'case',case_text,'question',coalesce(old_content->>'question','Quale elemento dello scenario decide se l’addetto può intervenire direttamente o deve interrompere l’azione e privilegiare allarme/esodo?'),'question_explanation','La risposta corretta non dipende dal coraggio dell’addetto ma da scenario, sicurezza personale, via di fuga, efficacia prevista del presidio e procedure. Punto chiave: '||focus,'common_errors',jsonb_build_array('Tentare lo spegnimento quando la via di fuga non è garantita o il fuoco è già oltre la capacità di intervento iniziale.','Usare un presidio senza verificarne idoneità, accessibilità o condizioni apparenti.','Aprire porte o accedere ad aree invase da fumo senza valutare il rischio di peggiorare lo scenario.','Confondere il ruolo dell’addetto con quello dei Vigili del Fuoco o di squadre specialistiche.','Trascurare allarme, esodo e comunicazione per concentrarsi esclusivamente sullo spegnimento.'),'teacher_activity',jsonb_build_object('prompt',case_text,'method',case when practical_unit then 'Dimostrazione guidata + esercitazione individuale/a piccoli gruppi + correzione immediata + ripetizione della sequenza + debriefing.' else 'Analisi di scenario con mappa del luogo, misure presenti, sequenza di decisione e confronto tra prevenzione, protezione e risposta in emergenza.' end,'debrief','Ricostruire sempre: prevenzione/controllo → rilevazione/allarme → decisione → esodo o intervento iniziale → comunicazione → arrivo dei soccorsi → ripristino e segnalazione. Evidenziare le condizioni di STOP.'),'operational',coalesce(old_content->'operational','{}'::jsonb)||jsonb_build_object('before',jsonb_build_array('Conosci procedure, vie di esodo, punti di raccolta, modalità di allarme e presidi del luogo di lavoro.','Controlla che vie, porte, accessi e presidi non siano ostruiti e segnala anomalie.','In esercitazione pratica verifica sempre dispositivo, area, posizione e via di fuga prima dell’uso.'),'during',jsonb_build_array('Dai o fai dare l’allarme secondo procedura.','Valuta se l’incendio è ancora affrontabile in sicurezza con i mezzi disponibili e senza perdere la via di fuga.','Mantieni comunicazione con gli altri addetti e favorisci l’esodo.','Usa i presidi solo secondo formazione pratica e caratteristiche dello scenario.'),'after',jsonb_build_array('Comunica ai soccorritori luogo, condizioni, materiali coinvolti e azioni già eseguite.','Segnala presidi utilizzati o anomalie riscontrate perché siano ripristinati.','Partecipa al debriefing e alla revisione delle procedure se l’evento o l’esercitazione evidenzia criticità.'),'if_problem',jsonb_build_array('Se il fuoco cresce, il fumo compromette visibilità/respirazione o la via di fuga non è sicura, interrompi l’intervento e allontanati.','Se il presidio non è idoneo o non è utilizzabile, non improvvisare alternative pericolose.','Se l’area presenta rischi specifici non controllati, attendi le squadre competenti e fornisci informazioni.'),'who_to_involve',jsonb_build_array('Altri addetti antincendio','Preposto/dirigente o coordinamento dell’emergenza secondo piano','Occupanti e persone da assistere secondo procedura','Vigili del Fuoco/112 secondo procedura aziendale','Manutentori o responsabili dei sistemi per ripristino e anomalie'),'stop_conditions',jsonb_build_array('Via di fuga non garantita.','Fumo, calore o propagazione incompatibili con intervento iniziale sicuro.','Presidio non idoneo, inefficiente o non conosciuto.','Rischio specifico — elettrico, esplosivo, chimico o strutturale — non sotto controllo.','Necessità di entrare in area che richiede DPI, autorespiratori o competenze non previste dal corso.'),'adaptation','Contestualizzare a valutazione del rischio incendio, livello dell’attività, piano di emergenza, affollamento, persone con esigenze specifiche, sostanze/processi e sistemi realmente presenti.'),'practical_component',jsonb_build_object('course_practice_required',true,'unit_is_practical',practical_unit,'completed_digitally',false,'level',level,'initial_course',jsonb_build_object('level_1',jsonb_build_object('total_minutes',240,'theory_minutes',120,'practice_minutes',120),'level_2',jsonb_build_object('total_minutes',480,'theory_minutes',300,'practice_minutes',180),'level_3',jsonb_build_object('total_minutes',960,'theory_minutes',720,'practice_minutes',240)),'update_course',jsonb_build_object('level_1',jsonb_build_object('total_minutes',120,'theory_minutes',0,'practice_minutes',120),'level_2',jsonb_build_object('total_minutes',300,'theory_minutes',120,'practice_minutes',180),'level_3',jsonb_build_object('total_minutes',480,'theory_minutes',300,'practice_minutes',180)),'qualification_note','Il materiale digitale e le schede delle esercitazioni non attestano da soli l’esecuzione della parte pratica prevista dal D.M. 2 settembre 2021.'),'scope_boundary','Materiale didattico per addetti antincendio ai sensi del D.M. 2 settembre 2021. Non sostituisce valutazione del rischio incendio, piano di emergenza, esercitazioni pratiche, addestramento sui presidi realmente presenti né l’intervento dei Vigili del Fuoco.','level',level,'renewal_months',case when family='update' then 60 else null end,'formative_check',jsonb_build_object('question',coalesce(old_content->>'question','Quale elemento dello scenario decide se l’addetto può intervenire direttamente o deve interrompere l’azione e privilegiare allarme/esodo?'),'explanation','Valutare via di fuga, sviluppo dell’incendio, fumo/calore, idoneità del presidio e procedure. La verifica in LU è formativa e non sostituisce la prova pratica.','formative_only',true,'test_builder_excluded',true),'graphic_cards',jsonb_build_array(jsonb_build_object('title','Prima l’allarme','body','Un intervento sul focolaio non deve ritardare l’attivazione della risposta di emergenza.'),jsonb_build_object('title','Via di fuga','body','Intervieni solo mantenendo sempre una possibilità sicura di arretramento e uscita.'),jsonb_build_object('title','Presidio giusto','body','Estintore, naspo o idrante vanno usati solo se coerenti con scenario, addestramento e condizioni di sicurezza.'),jsonb_build_object('title','STOP','body','Se fumo, calore, propagazione o rischi specifici superano l’intervento iniziale, interrompi e lascia spazio ai soccorritori.')),'didactic_version','fire-authored-v3','source_keys',source_keys,'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16','normative_validation','D.Lgs. 81/2008 art.46 + D.M. 2 settembre 2021 Allegato III','reuse_policy','reference_and_original_rewrite'),'source_integration_note','Norma e materiali VVF usati come riferimento per programmi, durate, limiti ed esercitazioni. Testi, casi, spiegazioni, diagrammi e sequenze operative SafetyTraining sono riscritti originali.','quality',coalesce(old_content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true,'practical_gate_explicit',true,'scope_boundary_explicit',true),'final_assessment',false,'test_builder_excluded',true) new_content from profiled), final_content as (select e.*,e.new_content||jsonb_build_object('evidence_sources',coalesce((select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(e.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key),'[]'::jsonb)) content_final from enriched e)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at) select learning_unit_id,target_version,'draft',content_final,md5(content_final::text),null from final_content on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;
with authored as (select lu.id learning_unit_id,luv.content->'source_keys' source_keys from public.learning_units lu join public.learning_unit_versions luv on luv.learning_unit_id=lu.id where luv.content->>'didactic_version'='fire-authored-v3' and luv.status='draft') insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) select a.learning_unit_id,sk.source_key,'authored_evidence_v3','Fonte usata per validazione normativa, approfondimento tecnico o metodo nella versione fire-authored-v3.',date '2026-10-16',jsonb_build_object('didactic_version','fire-authored-v3','reuse_policy','reference_and_original_rewrite') from authored a cross join lateral jsonb_array_elements_text(a.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
do $$ declare n integer;base_n integer;upd_n integer;links integer;bad integer;mappings integer;catalog_ok integer; begin select count(*) into n from public.learning_unit_versions where content->>'didactic_version'='fire-authored-v3' and status='draft'; if n<>23 then raise exception 'expected 23 fire-authored-v3 drafts, got %',n; end if; select count(*) into base_n from public.learning_unit_versions luv join public.learning_units lu on lu.id=luv.learning_unit_id where luv.content->>'didactic_version'='fire-authored-v3' and lu.stable_key not like 'fire:upd:%'; select count(*) into upd_n from public.learning_unit_versions luv join public.learning_units lu on lu.id=luv.learning_unit_id where luv.content->>'didactic_version'='fire-authored-v3' and lu.stable_key like 'fire:upd:%'; if base_n<>17 or upd_n<>6 then raise exception 'expected 17 base + 6 update, got % + %',base_n,upd_n; end if; select count(*) into links from public.course_module_units cmu join public.learning_unit_versions luv on luv.id=cmu.unit_version_id where luv.content->>'didactic_version'='fire-authored-v3'; if links<>0 then raise exception 'fire authored drafts unexpectedly linked: %',links; end if; select count(*) into bad from public.learning_unit_versions luv where luv.content->>'didactic_version'='fire-authored-v3' and (luv.content->'quality'->>'teacher_ready' is distinct from 'true' or luv.content->'quality'->>'learner_ready' is distinct from 'true' or luv.content->'quality'->>'question_has_explanation' is distinct from 'true' or luv.content->'quality'->>'test_builder_excluded' is distinct from 'true' or luv.content->'quality'->>'practical_gate_explicit' is distinct from 'true' or luv.content->>'final_assessment' is distinct from 'false' or luv.content->'practical_component'->>'completed_digitally' is distinct from 'false' or jsonb_array_length(coalesce(luv.content->'evidence_sources','[]'::jsonb))<3); if bad<>0 then raise exception 'quality assertions failed for % units',bad; end if; select count(*) into mappings from public.training_blueprint_course_types where blueprint_key in ('fire_initial','fire_update') and metadata->>'mapped_course_key' in ('antincendio_l1','antincendio','antincendio_l3','agg_antincendio_l1','agg_antincendio_l2','agg_antincendio_l3'); if mappings<>6 then raise exception 'fire blueprint mappings invalid: %',mappings; end if; select count(*) into catalog_ok from public.courses where active=true; if catalog_ok<>92 then raise exception 'active catalog expected 92 got %',catalog_ok; end if; end $$;